author:
  - Ansible Core Team
"""

EXAMPLES = r"""
- name: Get mount facts
  ansible.builtin.mount_facts:

- name: Get mount facts from fstab only
  ansible.builtin.mount_facts:
    sources: [static]
"""

RETURN = r"""
ansible_facts:
  description: Mount facts.
  returned: always
  type: dict
"""

import dataclasses
import functools
import os
import re
import subprocess
import time

from collections import defaultdict
from typing import Iterable, Optional

from ansible.module_utils.basic import AnsibleModule
from ansible.module_utils.common.text.converters import to_native
from ansible.module_utils.facts.utils import get_file_content

# Source aliases and their expansions.
STATIC_SOURCES = ["/etc/fstab", "/etc/vfstab", "/etc/filesystems"]
DYNAMIC_SOURCES = ["/etc/mtab", "/proc/mounts", "/etc/mnttab"]
ALL_SOURCES = DYNAMIC_SOURCES + STATIC_SOURCES

ANSIBLE_CONTEXT = "ansible_context"


class TimeoutError(Exception):
    pass


@dataclasses.dataclass
class MountInfo:
    mount_point: str
    line: str
    fields: dict


@dataclasses.dataclass
class MountInfoOptions:
    mount_point: str
    line: str
    fields: dict


def get_argument_spec():
    return dict(
        sources=dict(type="list", elements="str", default=None),
        mount_binary=dict(type="raw", default="mount"),
        devices=dict(type="list", elements="str", default=None),
        fstypes=dict(type="list", elements="str", default=None),
        timeout=dict(type="float", default=None),
        on_timeout=dict(type="str", default="error", choices=["error", "warn", "ignore"]),
        include_aggregate_mounts=dict(type="bool", default=None),
    )


def replace_octal_escapes(value):
    return re.sub(r"\\([0-7]{3})", lambda m: chr(int(m.group(1), 8)), value)


def handle_timeout(module, default=None):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            try:
                return func(*args, **kwargs)
            except TimeoutError as e:
                on_timeout = module.params["on_timeout"]
                if on_timeout == "error":
                    module.fail_json(msg=to_native(e))
                elif on_timeout == "warn":
                    module.warn(to_native(e))
                return default

        return wrapper

    return decorator


def get_sources(module):
    sources = module.params["sources"]
    if sources is None:
        sources = ["all"]

    if "" in sources:
        module.fail_json(msg="sources contains an empty string")

    resolved = []
    for source in sources:
        if source == "all":
            resolved.extend(ALL_SOURCES)
        elif source == "static":
            resolved.extend(STATIC_SOURCES)
        elif source == "dynamic":
            resolved.extend(DYNAMIC_SOURCES)
        else:
            resolved.append(source)

    if len(set(resolved)) != len(resolved):
        module.warn(
            "mount_facts option 'sources' contains duplicate entries, repeat sources will be ignored: %s"
            % resolved
        )

    return resolved


def gen_fstab_entries(lines):
    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        fields = stripped.split()
        if len(fields) < 4:
            raise ValueError("invalid fstab line")
        entry = {
            "device": fields[0],
            "mount": fields[1],
            "fstype": fields[2],
            "options": fields[3],
        }
        if len(fields) >= 6:
            entry["dump"] = int(fields[4])
            entry["passno"] = int(fields[5])
        yield MountInfo(fields[1], line, entry)


def gen_vfstab_entries(lines):
    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        fields = stripped.split()
        if len(fields) < 7:
            raise ValueError("invalid vfstab line")
        passno = fields[4]
        if passno.isdigit():
            passno = int(passno)
        entry = {
            "device": fields[0],
            "device_to_fsck": fields[1],
            "mount": fields[2],
            "fstype": fields[3],
            "passno": passno,
            "mount_at_boot": fields[5],
            "options": fields[6],
        }
        yield MountInfo(fields[2], line, entry)


def gen_mnttab_entries(lines):
    lines = list(lines)
    if not any(len(line.split()) >= 3 and len(line.split()[2]) == 10 for line in lines if line.strip()):
        raise ValueError("not mnttab")
    for line in lines:
        fields = line.split()
        if len(fields) < 5:
            raise ValueError("invalid mnttab line")
        entry = {
            "device": fields[0],
            "mount": fields[1],
            "fstype": fields[2],
            "options": fields[3],
            "time": int(fields[4]),
        }
        yield MountInfo(fields[1], line, entry)


def list_aix_filesystems_stanzas(lines):
    stanzas = []
    current = None
    for line in lines:
        if not line.strip() or line.startswith("*"):
            continue
        if not line.startswith((" ", "\t")) and line.rstrip().endswith(":"):
            current = [line]
            stanzas.append(current)
        elif current is not None:
            current.append(line)
        else:
            return []
    return stanzas


def gen_aix_filesystems_entries(lines):
    for stanza in list_aix_filesystems_stanzas(lines):
        mount_point = stanza[0].strip().rstrip(":")
        attributes = {}
        for line in stanza[1:]:
            stripped = line.strip()
            if "=" in stripped:
                key, value = stripped.split("=", 1)
                attributes[key.strip()] = value.strip()
        device = attributes.get("dev", "unknown")
        if "nodename" in attributes and "dev" in attributes:
            device = "%s:%s" % (attributes["nodename"], attributes["dev"])
        fields = {
            "mount": mount_point,
            "device": device,
            "fstype": attributes.get("vfs", "unknown"),
            "attributes": attributes,
        }
        line = "\n".join(stanza)
        yield MountInfoOptions(mount_point, line, fields)


def get_mount_pattern(stdout):
    lines = stdout.splitlines()
    if not lines:
        return None
    linux = re.compile(r"^(?P<device>\S+) on (?P<mount>\S+) type (?P<fstype>\S+) \((?P<options>.*)\)$")
    bsd = re.compile(r"^(?P<device>\S+) on (?P<mount>\S+) \((?P<fstype_options>.*)\)$")
    aix = re.compile(r"^(?P<mount>\S+)\s+(?P<node>\S*)\s+(?P<device>\S+)\s+(?P<time>\w+\s+\d+\s+\d+:\d+)\s+(?P<options>.*)$")
    for line in lines:
        if linux.match(line):
            return linux
    for line in lines:
        if bsd.match(line):
            return bsd
    if len(lines) > 2 and aix.match(lines[2]):
        return aix
    return None


def gen_mounts_from_stdout(stdout):
    pattern = get_mount_pattern(stdout)
    if pattern is None:
        return
    lines = stdout.splitlines()
    if pattern.pattern.startswith("^(?P<mount>"):
        lines = lines[2:]
    for line in lines:
        match = pattern.match(line)
        if not match:
            continue
        if pattern is bsd_pattern_marker():
            pass
        groups = match.groupdict()
        if "fstype_options" in groups:
            fstype, _, options = groups["fstype_options"].partition(",")
            fields = {"device": groups["device"], "mount": groups["mount"], "fstype": fstype.strip()}
            if options:
                fields["options"] = options.strip()
            yield MountInfo(groups["mount"], line, fields)
        elif "time" in groups:
            device = groups["device"]
            if groups["node"]:
                device = "%s:%s" % (groups["node"], device)
            fields = {
                "device": device,
                "mount": groups["mount"],
                "fstype": "unknown",
                "time": groups["time"],
                "options": groups["options"],
            }
            yield MountInfo(groups["mount"], line, fields)
        else:
            fields = {
                "device": groups["device"],
                "mount": groups["mount"],
                "fstype": groups["fstype"],
                "options": groups["options"],
            }
            yield MountInfo(groups["mount"], line, fields)


def bsd_pattern_marker():
    return None


def run_mount_bin(module, mount_bin):
    timeout = module.params["timeout"]
    bin_path = module.get_bin_path(mount_bin, required=True)
    try:
        return subprocess.check_output(bin_path, text=True, timeout=timeout)
    except subprocess.TimeoutExpired:
        raise TimeoutError("Command '%s' timed out after %s seconds" % (bin_path, timeout))
    except subprocess.CalledProcessError as e:
        module.fail_json(msg="Failed to execute %s: %s" % (bin_path, to_native(e)))


def get_mount_size(mount):
    try:
        return os.statvfs(mount)
    except OSError:
        return None


def get_mount_size_stats(module, mount):
    timeout = module.params["timeout"]
    if timeout is None:
        return get_mount_size(mount)
    start = time.time()
    result = get_mount_size(mount)
    if time.time() - start > timeout:
        raise TimeoutError("Timer expired after %s seconds" % timeout)
    return result


def gen_mounts_by_file(file):
    if not os.path.exists(file):
        return
    content = get_file_content(file)
    if not content:
        return
    lines = content.splitlines()
    for parser in (gen_vfstab_entries, gen_mnttab_entries, gen_fstab_entries, gen_aix_filesystems_entries):
        try:
            entries = list(parser(lines))
        except (ValueError, IndexError):
            continue
        for entry in entries:
            yield entry
        return


def gen_mounts_by_source(module):
    sources = get_sources(module)
    seen = set()
    for source in sources:
        if source in seen:
            continue
        seen.add(source)
        if source == "mount":
            for entry in gen_mounts_from_stdout(run_mount_bin(module, module.params["mount_binary"])):
                yield ("mount", entry.mount_point, entry.line, entry.fields)
            continue
        for entry in gen_mounts_by_file(source):
            yield (source, entry.mount_point, entry.line, entry.fields)


