class AbstractSolrUpdater(ABC):
    """Shared contract for record-specific Solr updaters."""

    key_prefix: str

    def __init__(self, data_provider: DataProvider | None = None):
        self._data_provider = data_provider

    def _provider(self) -> DataProvider:
        return self._data_provider if self._data_provider is not None else data_provider

    def key_test(self, key: str) -> bool:
        """Whether this updater handles the given key."""
        return key.startswith(self.key_prefix)

    async def preload_keys(self, keys: Iterable[str]) -> None:
        await self._provider().preload_documents(set(keys))

    @abstractmethod
    async def update_key(self, thing: dict) -> SolrUpdateState:
        """Produce the Solr update state for one record document."""
        raise NotImplementedError


