            logger.warning("Found redirect to %s", thing['location'])
            # The redirect's own key must go; the target takes its place.
            update.deletes.append(key)
            target = await self._provider().get_document(thing['location'])
            if not target:
                return update
            if target['key'].startswith(self.key_prefix):
                return update + await self.update_key(target)
            update.keys.append(target['key'])
            return update

        if thing_type == '/type/delete':
            update.deletes.append(key)
        elif thing_type == '/type/edition':
            work_key = key.replace('/books/', '/works/', 1)
            if thing.get('works'):
