from openlibrary.core.bookshelves import Bookshelves

from . import db


class Bestbook(db.CommonExtras):
    TABLENAME = "bestbooks"
    PRIMARY_KEY = ["award_id"]

    class AwardConditionsError(Exception):
        pass

    @classmethod
    def prepare_query(cls, select="*", work_id=None, username=None, topic=None):
        where = []
        data = {}
        if work_id:
            where.append("work_id=$work_id")
            data["work_id"] = work_id
        if username:
            where.append("username=$username")
            data["username"] = username
        if topic:
            where.append("topic=$topic")
            data["topic"] = topic
        query = f"SELECT {select} FROM {cls.TABLENAME}"
        if where:
            query += " WHERE " + " AND ".join(where)
        return query, data

    @classmethod
    def get_count(cls, work_id=None, username=None, topic=None) -> int:
        query, data = cls.prepare_query(
            "count(*)", work_id=work_id, username=username, topic=topic
        )
        result = db.get_db().query(query, vars=data)
        return result[0]['count'] if result else 0

    @classmethod
    def get_awards(cls, work_id=None, username=None, topic=None) -> list:
        query, data = cls.prepare_query(
            "*", work_id=work_id, username=username, topic=topic
        )
        return list(db.get_db().query(query, vars=data))

    @classmethod
    def get_leaderboard(cls) -> list[dict]:
        query = (
            f"SELECT work_id, count(*) AS count FROM {cls.TABLENAME} "
            "GROUP BY work_id ORDER BY count DESC"
        )
        return [dict(r) for r in db.get_db().query(query)]

    @classmethod
    def _check_award_conditions(cls, username, work_id, topic):
        errors = []
        if not Bookshelves.user_has_read_work(username=username, work_id=work_id):
            errors.append(
                "Only books which have been marked as read may be given awards"
            )
        if cls.get_awards(username=username, work_id=work_id):
            errors.append("A work may only be nominated one time for a best book award")
        for a in cls.get_awards(username=username, topic=topic) or []:
            aw = a.get('work_id') if hasattr(a, 'get') else None
            if str(aw) != str(work_id):
                errors.append(
                    f"A topic may only be nominated one time for a best book award: "
                    f"The work {aw} has already been nominated for topic {topic}"
                )
                break
        if errors:
            raise cls.AwardConditionsError(" ".join(errors))
        return True

    @classmethod
    def add(cls, username, work_id, topic, comment="", edition_id=None):
        cls._check_award_conditions(username, work_id, topic)
        return db.get_db().insert(
            cls.TABLENAME,
            username=username,
            work_id=work_id,
            edition_id=edition_id,
            topic=topic,
            comment=comment or "",
        )

    @classmethod
    def remove(cls, username, work_id=None, topic=None) -> int:
        if not (work_id or topic):
            raise ValueError("Either work_id or topic must be specified")
        conds = []
        data = {'username': username}
        if work_id:
            conds.append("work_id=$work_id")
            data['work_id'] = work_id
        if topic:
            conds.append("topic=$topic")
            data['topic'] = topic
        where = "username=$username AND (" + " OR ".join(conds) + ")"
        return db.get_db().delete(cls.TABLENAME, where=where, vars=data)
